// GraphNodeAttachResourceConfig is an interface that must be implemented by nodes
// that want resource configurations attached.
type GraphNodeAttachResourceConfig interface {
	GraphNodeConfigResource

	// Sets the configuration, either to a present resource block or to
	// a "removed" block commemorating a resource that has since been
	// removed. Callers should always leave at least one of these
	// arguments set to nil.
	AttachResourceConfig(*configs.Resource, *configs.Removed)
}

// AttachResourceConfigTransformer goes through the graph and attaches
// resource configuration structures to nodes that implement
// GraphNodeAttachManagedResourceConfig or GraphNodeAttachDataResourceConfig.
//
// The attached configuration structures are directly from the configuration.
// If they're going to be modified, a copy should be made.
type AttachResourceConfigTransformer struct {
	Config *configs.Config // Config is the root node in the config tree

	resourceConfigIndex map[string]*configs.Resource
	removedBlockIndex   map[string]*configs.Removed
	providerMetaIndex   map[string]map[addrs.Provider]*configs.ProviderMeta

	resourceStateIndex map[string]*states.Resource
	missingStateKeys   []string

	resourceSchemaIndex    map[string]*configschema.Block
	providerSchemaIndex    map[string]*configschema.Block
	provisionerSchemaIndex map[string]*configschema.Block
	schemaVersions         map[string]uint64

	orphanInstanceKeys []string
	removedModuleKeys  []string
}

func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {

	// Go through and find GraphNodeAttachResource
	for _, v := range g.Vertices() {
		// Only care about GraphNodeAttachResource implementations
		arn, ok := v.(GraphNodeAttachResourceConfig)
		if !ok {
			continue
		}

		// Determine what we're looking for
		addr := arn.ResourceAddr()

		// Get the configuration.
		config := t.Config.Descendent(addr.Module)

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", dag.VertexName(v), v)
			continue
		}

		if r := config.Module.ResourceByAddr(addr.Resource); r != nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", dag.VertexName(v), v, r.DeclRange)
			arn.AttachResourceConfig(r, nil)
			if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", dag.VertexName(v))
				if config.Module.ProviderMetas != nil {
					gnapmc.AttachProviderMetaConfigs(config.Module.ProviderMetas)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", dag.VertexName(v))
				}
			}
		}

		for _, r := range config.Module.Removed {
			crAddr, ok := r.From.RelSubject.(addrs.ConfigResource)
			if !ok {
				// Not for a resource at all, so can't possibly match
				continue
			}
			rAddr := crAddr.Resource
			if rAddr != addr.Resource {
				// Not the same resource
				continue
			}

			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", dag.VertexName(v), v, r.DeclRange)

			// Validation ensures that there can't be both a resource/data block
			// and a removed block referring to the same configuration, so
			// we can assume that this isn't clobbering a non-removed resource
			// configuration we already attached above.
			arn.AttachResourceConfig(nil, r)
		}
	}

	return nil
}

func (t *AttachResourceConfigTransformer) ensureResourceConfigIndex() {
	if t.resourceConfigIndex == nil {
		t.resourceConfigIndex = make(map[string]*configs.Resource)
	}
	if t.removedBlockIndex == nil {
		t.removedBlockIndex = make(map[string]*configs.Removed)
	}
	if t.providerMetaIndex == nil {
		t.providerMetaIndex = make(map[string]map[addrs.Provider]*configs.ProviderMeta)
	}
	if len(t.resourceConfigIndex) == 0 && len(t.removedBlockIndex) == 0 && len(t.providerMetaIndex) == 0 {
		return
	}
	if t.resourceConfigIndex != nil && t.removedBlockIndex != nil && t.providerMetaIndex != nil {
		return
	}
}

func (t *AttachResourceConfigTransformer) indexConfigTree(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || t.resourceConfigIndex == nil {
		return
	}

	seen := map[string]bool{}
	queue := []*configs.Config{cfg}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if current == nil || current.Module == nil {
			continue
		}

		pathKey := current.Path.String()
		if seen[pathKey] {
			continue
		}
		seen[pathKey] = true

		t.indexModuleResources(current)
		t.indexModuleRemovedBlocks(current)
		t.rememberProviderMetas(current)

		if current.Children == nil {
			continue
		}
		for name, child := range current.Children {
			if child == nil {
				continue
			}
			if name == "" && !child.Path.IsRoot() {
				queue = append(queue, child)
				continue
			}
			queue = append(queue, child)
		}
	}
}

func (t *AttachResourceConfigTransformer) indexModuleResources(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return
	}

	moduleKey := cfg.Path.String()
	for _, r := range cfg.Module.ManagedResources {
		if r == nil {
			continue
		}
		addr := r.Addr()
		key := moduleKey + "|" + addr.String()
		if moduleKey == "" {
			key = addr.String()
		}
		t.resourceConfigIndex[key] = r
		if r.Count != nil {
			t.resourceConfigIndex[key+":count"] = r
		}
		if r.ForEach != nil {
			t.resourceConfigIndex[key+":for_each"] = r
		}
		if r.Managed != nil && len(r.Managed.Provisioners) > 0 {
			t.resourceConfigIndex[key+":provisioned"] = r
			for _, p := range r.Managed.Provisioners {
				if p == nil {
					continue
				}
				if p.When == configs.ProvisionerWhenDestroy {
					t.resourceConfigIndex[key+":destroy-provisioner"] = r
				} else if p.When == configs.ProvisionerWhenCreate {
					t.resourceConfigIndex[key+":create-provisioner"] = r
				}
			}
		}
	}

	for _, r := range cfg.Module.DataResources {
		if r == nil {
			continue
		}
		addr := r.Addr()
		key := moduleKey + "|" + addr.String()
		if moduleKey == "" {
			key = addr.String()
		}
		t.resourceConfigIndex[key] = r
		if r.Count != nil {
			t.resourceConfigIndex[key+":count"] = r
		} else if r.ForEach != nil {
			t.resourceConfigIndex[key+":for_each"] = r
		}
	}
}

func (t *AttachResourceConfigTransformer) indexModuleRemovedBlocks(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return
	}

	for _, rem := range cfg.Module.Removed {
		if rem == nil || rem.From == nil {
			continue
		}

		switch subj := rem.From.RelSubject.(type) {
		case addrs.ConfigResource:
			key := subj.Module.String() + "|" + subj.Resource.String()
			if subj.Module.IsRoot() {
				key = subj.Resource.String()
			}
			t.removedBlockIndex[key] = rem
			if rem.Destroy {
				t.removedBlockIndex[key+":destroy"] = rem
			}
			if rem.Managed != nil {
				t.removedBlockIndex[key+":managed"] = rem
				if len(rem.Managed.Provisioners) > 0 {
					t.removedBlockIndex[key+":provisioned"] = rem
					for _, p := range rem.Managed.Provisioners {
						if p == nil {
							continue
						}
						if p.When == configs.ProvisionerWhenDestroy {
							t.removedBlockIndex[key+":destroy-provisioner:"+p.Type] = rem
						}
					}
				}
			}
		case addrs.Module:
			t.removedBlockIndex["module:"+subj.String()] = rem
			if rem.Destroy {
				t.removedBlockIndex["module:"+subj.String()+":destroy"] = rem
			}
		default:
			continue
		}
	}
}

func (t *AttachResourceConfigTransformer) rememberProviderMetas(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return
	}

	pathKey := cfg.Path.String()
	if cfg.Path.IsRoot() {
		pathKey = ""
	}

	metas := cfg.Module.ProviderMetas
	if metas == nil {
		t.providerMetaIndex[pathKey] = nil
		return
	}

	copied := make(map[addrs.Provider]*configs.ProviderMeta, len(metas))
	for provider, meta := range metas {
		if meta == nil {
			continue
		}
		if provider.Type == "" && provider.Namespace == "" && provider.Hostname == "" {
			continue
		}
		copied[provider] = meta
		if provider.Type != "" {
			t.providerMetaIndex[pathKey+"|"+provider.Type] = copied
		}
	}
	t.providerMetaIndex[pathKey] = copied
}

func (t *AttachResourceConfigTransformer) lookupIndexedResource(module addrs.Module, res addrs.Resource) *configs.Resource {
	t.ensureResourceConfigIndex()
	moduleKey := module.String()
	key := moduleKey + "|" + res.String()
	if module.IsRoot() || moduleKey == "" {
		key = res.String()
	}

	if found, ok := t.resourceConfigIndex[key]; ok && found != nil {
		return found
	}

	switch res.Mode {
	case addrs.ManagedResourceMode:
		if found, ok := t.resourceConfigIndex[key+":count"]; ok && found != nil {
			return found
		}
		if found, ok := t.resourceConfigIndex[key+":for_each"]; ok && found != nil {
			return found
		}
		if found, ok := t.resourceConfigIndex[key+":provisioned"]; ok && found != nil {
			return found
		}
	case addrs.DataResourceMode:
		if found, ok := t.resourceConfigIndex[key+":count"]; ok && found != nil {
			return found
		}
		if found, ok := t.resourceConfigIndex[key+":for_each"]; ok && found != nil {
			return found
		}
	default:
		return nil
	}
	return nil
}

func (t *AttachResourceConfigTransformer) lookupIndexedRemoved(resAddr addrs.ConfigResource) *configs.Removed {
	t.ensureResourceConfigIndex()
	key := resAddr.Module.String() + "|" + resAddr.Resource.String()
	if resAddr.Module.IsRoot() {
		key = resAddr.Resource.String()
	}

	if found, ok := t.removedBlockIndex[key]; ok {
		return found
	}
	if found, ok := t.removedBlockIndex[key+":destroy"]; ok {
		return found
	}
	if found, ok := t.removedBlockIndex[key+":managed"]; ok {
		return found
	}
	if found, ok := t.removedBlockIndex[key+":provisioned"]; ok {
		return found
	}
	if resAddr.Resource.Mode == addrs.DataResourceMode {
		return nil
	}
	if resAddr.Resource.Mode == addrs.ManagedResourceMode {
		return t.removedBlockIndex[key+":destroy-provisioner:local-exec"]
	}
	return nil
}

func (t *AttachResourceConfigTransformer) moduleConfigForState(cfg *configs.Config, ms *states.Module) *configs.Module {
	t.ensureResourceConfigIndex()
	if cfg == nil || ms == nil {
		return nil
	}

	c := cfg.DescendentForInstance(ms.Addr)
	if c == nil || c.Module == nil {
		missingKey := "missing-module:" + ms.Addr.String()
		if _, exists := t.resourceConfigIndex[missingKey]; !exists {
			t.resourceConfigIndex[missingKey] = nil
		}
		if rem := t.lookupIndexedRemoved(addrs.ConfigResource{Module: ms.Addr.Module()}); rem != nil {
			t.removedBlockIndex["state-module:"+ms.Addr.String()] = rem
		}
		return nil
	}

	t.indexModuleResources(c)
	t.indexModuleRemovedBlocks(c)
	t.rememberProviderMetas(c)
	return c.Module
}

func (t *AttachResourceConfigTransformer) expandConfigResources(g *Graph, cfg *configs.Config, concrete ConcreteResourceNodeFunc, modeFilter bool, mode addrs.ResourceMode, importTargets []*ImportTarget, skip bool, generateConfigPath string) error {
	if skip {
		return nil
	}
	if cfg == nil {
		return nil
	}

	t.ensureResourceConfigIndex()
	if t.resourceConfigIndex == nil || t.removedBlockIndex == nil {
		return nil
	}
